import java.util.Scanner; public class Solution { public static String encryption(String s) { String text = s.replaceAll("\\s+", ""); int L = text.length(); int sqrt = (int) Math.sqrt(L); int rows = sqrt; int cols = sqrt; if (rows * cols < L) { rows = cols + 1; } if (rows * cols < L) { cols = rows; } StringBuilder result = new StringBuilder(); for (int c = 0; c < cols; c++) { for (int r = 0; r < rows; r++) { int index = r * cols + c; if (index < L) { result.append(text.charAt(index)); } } if (c < cols - 1) { result.append(" "); } } return result.toString(); } public static void main(String[] args) { Scanner scanner = new Scanner(System.in); if (scanner.hasNextLine()) { String s = scanner.nextLine(); System.out.println(encryption(s)); } scanner.close(); } }